/**
 * Vendor the agent roles from ECC (affaan-m/ecc, MIT) so a Bot can start from
 * one. Each role's Markdown is read at one pinned commit, its front matter gives
 * the name and description, and the body is kept as the working method the Bot
 * follows. The result is one generated file, frontend/src/content/ecc/agents.ts.
 *
 * Usage:
 *   node scripts/vendor-ecc-agents.mjs                 # fetch over HTTPS (api.github.com)
 *   node scripts/vendor-ecc-agents.mjs --from <dir>    # read <dir>/agents/<name>.md from a checkout
 *
 * Nothing here rewrites the role's text. The body is cut only at MAX_PROMPT
 * characters, and the cut is marked.
 */
import { writeFileSync, readFileSync, existsSync, mkdirSync } from 'node:fs'
import { join, dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const repoRoot = resolve(here, '..')
const outPath = resolve(repoRoot, 'frontend/src/content/ecc/agents.ts')

const REPO = 'affaan-m/ecc'
const REF = '76aaa77df6adc5b889e689007bf99b9a4f74af34'
const LICENSE = 'MIT'
const CREDIT = 'Affaan Mustafa — Everything Claude Code (ECC), agent roles'
const MAX_PROMPT = 12000

const AGENTS = [
  'planner',
  'architect',
  'tdd-guide',
  'code-reviewer',
  'security-reviewer',
  'seo-specialist',
  'docs-lookup',
  'doc-updater',
]

const args = process.argv.slice(2)
const fromIdx = args.indexOf('--from')
const fromDir = fromIdx >= 0 ? resolve(args[fromIdx + 1]) : null

function split(text) {
  const m = String(text).match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/)
  if (!m) return { meta: {}, body: String(text) }
  const meta = {}
  for (const line of m[1].split('\n')) {
    const kv = line.match(/^([a-z-]+):\s*(.+)$/)
    if (kv) meta[kv[1]] = kv[2].trim().replace(/^["']|["']$/g, '')
  }
  return { meta, body: m[2].trim() }
}

async function load(name) {
  if (fromDir) {
    const p = join(fromDir, 'agents', `${name}.md`)
    if (!existsSync(p)) throw new Error(`missing ${p}`)
    return readFileSync(p, 'utf8')
  }
  const url = `https://api.github.com/repos/${REPO}/contents/agents/${name}.md?ref=${REF}`
  const res = await fetch(url, { headers: { Accept: 'application/vnd.github.raw', 'User-Agent': 'research-engine-vendor' } })
  if (!res.ok) throw new Error(`${res.status} ${res.statusText} for ${url}`)
  return res.text()
}

const entries = []
for (const name of AGENTS) {
  const { meta, body } = split(await load(name))
  const prompt = body.length > MAX_PROMPT ? `${body.slice(0, MAX_PROMPT)}\n\n(role truncated at ${MAX_PROMPT} characters)` : body
  entries.push({
    id: name,
    name: meta.name || name,
    description: meta.description || '',
    prompt,
    origin: REPO,
    license: LICENSE,
    credit: CREDIT,
    ref: REF,
  })
  console.log(`  agents/${name}.md  ${body.length} chars`)
}

mkdirSync(dirname(outPath), { recursive: true })
writeFileSync(outPath, [
  '/**',
  ' * Agent roles vendored from affaan-m/ecc (MIT), at one pinned commit.',
  ' * Generated by scripts/vendor-ecc-agents.mjs. Do not edit by hand.',
  ' */',
  'export interface EccAgent {',
  '  id: string',
  '  name: string',
  '  description: string',
  '  prompt: string',
  '  origin: string',
  '  license: string',
  '  credit: string',
  '  ref: string',
  '}',
  `export const ECC_REF = ${JSON.stringify(REF)}`,
  `export const ECC_AGENTS: EccAgent[] = ${JSON.stringify(entries, null, 1)}`,
  '',
].join('\n'))
console.log(`agents: ${entries.length} roles -> ${outPath}`)
